files = repo.list("logs")
content = repo.read("logs/service.log", missing_ok=True)
if content == None:
    return {"dir": files, "error": "logs/service.log not found"}
lines = content.split("\n")
hits = []
for i, l in enumerate(lines):
    if "ALERT" in l:
        hits.append(i)
out = []
for i in hits:
    out.append({
        "line_number": i + 1,
        "prev": lines[i-1] if i > 0 else None,
        "match": lines[i],
        "next": lines[i+1] if i + 1 < len(lines) else None,
    })
return {"dir": files, "total_lines": len(lines), "hits": out}
